-- V8: CRM 国家参考数据（国家 -> 时区 / 当前时间 / 主要货币 / 对美元与人民币汇率）
-- 约定（见 docs/crm-backend-requirements.md §5.1）：
--   * MySQL 8 / utf8mb4_unicode_ci
--   * 不建物理外键，关联关系由 Service 层维护（逻辑 mapping）
--   * 主键 VARCHAR(36)，应用层生成 UUID
--   * 参考数据表与字典表一致，不设 deleted（不参与业务逻辑删除）
--
-- 数据来源（构建期一次性抓取，运行期**不依赖任何外部接口**）：
--   * 国家名 / 中文名 / 货币：world-countries v5（jsDelivr CDN）
--   * 国家 -> 时区：IANA tzdb zone.tab
-- 汇率不在本表 —— 汇率由汇率同步任务写入 t_currency_rate（基准币 USD），本表只存币种码。

CREATE TABLE `t_country_ref` (
    `id` VARCHAR(36) NOT NULL,
    `country_code` CHAR(2) NOT NULL COMMENT 'ISO 3166-1 alpha-2 国家码',
    `country_name` VARCHAR(128) NOT NULL COMMENT '英文名',
    `country_name_zh` VARCHAR(128) DEFAULT NULL COMMENT '中文名',
    `country_aliases` VARCHAR(255) DEFAULT NULL COMMENT '常用口语 / 旧称，逗号分隔（搜索用）',
    `timezone` VARCHAR(64) NOT NULL COMMENT '主时区（IANA 区名，如 America/New_York）',
    `timezones` VARCHAR(1024) DEFAULT NULL COMMENT '该国全部时区，逗号分隔',
    `currency_code` CHAR(3) NOT NULL COMMENT '主要货币 → ISO 4217',
    `currency_name` VARCHAR(128) DEFAULT NULL COMMENT '货币名称',
    `currency_symbol` VARCHAR(16) DEFAULT NULL COMMENT '货币符号',
    `is_common` TINYINT NOT NULL DEFAULT 0 COMMENT '常用外贸国家标记（前端下拉置顶）',
    `create_time` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `update_time` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_country_code` (`country_code`),
    KEY `idx_currency` (`currency_code`),
    KEY `idx_common` (`is_common`),
    KEY `idx_aliases` (`country_aliases`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 国家参考数据';

